def resolve_revoke_decree_target_ids(
    self, payload: object, row: object = None,
) -> tuple[int, int]:
    """撤令目标解析唯一实现：(dossier_id, issue_id)。

    撤令的三处读者共用本函数——判后物化（#523）、判前供料
    （materials.revoke_target_facts）。读同一组结构化身份字段
    ``revoke_target_dossier_id`` / ``revoke_target_issue_id``；两者皆无
    时才按案卷行 ``target_kind``/``target_id`` 解析（接受 ``dossier:``/
    ``issue:`` 前缀），issue 再经 ``origin_ref`` 回指案卷。两个字段可同时
    在场（撤的是某道旨下出的承诺），**不得**读到其一即止。

    无合法案卷来源时响亮拒绝；只读供料方按「无原旨可读」捕获。
    """
    from ming_sim.strict_types import strict_int

    source = payload if isinstance(payload, Mapping) else {}
    fields = row if isinstance(row, Mapping) else {}

    def _id(key: str) -> int:
        try:
            return strict_int(source.get(key), accept_numeric_strings=True)
        except (TypeError, ValueError):
            return 0

    target_dossier_id = _id("revoke_target_dossier_id")
    target_issue_id = _id("revoke_target_issue_id")

    if target_dossier_id <= 0 and target_issue_id <= 0:
        raw = str(
            source.get("target_id") or fields.get("target_id") or ""
        ).strip()
        kind = str(
            source.get("target_kind") or fields.get("target_kind") or ""
        ).strip()
        if raw.startswith("dossier:"):
            kind, raw = "dossier", raw.split(":", 1)[1].strip()
        elif raw.startswith("issue:"):
            kind, raw = "issue", raw.split(":", 1)[1].strip()
        try:
            tid = strict_int(raw, accept_numeric_strings=True) if raw else 0
        except (TypeError, ValueError):
            tid = 0
        if tid <= 0:
            raise ValueError("撤回成命案卷缺少目标")
        if kind == "issue":
            target_issue_id = tid
        else:
            target_dossier_id = tid

    # issue 目标：经 origin_ref 回指案卷；无合法案卷来源不得免代价终结
    if target_dossier_id <= 0 and target_issue_id > 0:
        issue_row = self.conn.execute(
            "SELECT kind, status, origin_ref FROM issues WHERE id=?",
            (int(target_issue_id),),
        ).fetchone()
        if issue_row is None:
            raise ValueError("撤回成命目标事项不存在")
        if str(issue_row["kind"] or "").strip() != "initiative":
            raise ValueError("撤回成命目标须为承诺/initiative")
        origin = str(issue_row["origin_ref"] or "").strip()
        if origin.startswith("dossier:"):
            try:
                target_dossier_id = int(origin.split(":", 1)[1])
            except (TypeError, ValueError):
                target_dossier_id = 0

    if target_dossier_id <= 0:
        # 删除 standalone issue 免代价旁路（dossier_id=0 仍 cancel_issue）
        raise ValueError("撤回成命目标无合法案卷来源，不得免代价终结")
    return int(target_dossier_id), int(target_issue_id)

def _payload_owned_person_duplicate(
    db: GameDB,
    item: Dict[str, object],
    *,
    current_office_type: str = "",
    llm_config=None,
) -> bool:
    dossier = _payload_owned_dossier_for_origin(db, item.get("origin_ref") or item.get("来源引用"))
    if dossier is None or dossier.get("action_type") not in {"appointment", "dismiss_assignment"}:
        return False
    payload = dossier["payload"]
    person = str(item.get("name") or item.get("人物") or "").strip()
    target = str(payload.get("_minister_name") or payload.get("minister_name") or dossier.get("target_id") or "").strip()
    payload_action = str(payload.get("_office_action") or "").strip()
    item_action = str(item.get("动作") or item.get("action") or "").strip()
    if not person or person != target:
        return False
    if payload_action == "罢免":
        return item_action in {"罢黜", "罢免"}
    if payload_action != "任命" or item_action not in {"任命", "调任"}:
        return False
    canonical_kwargs = {
        "current_office_type": current_office_type,
        "llm_config": llm_config,
    }

    def _fields(src: Dict[str, object]) -> tuple[str, str, str, str]:
        office, office_type, tenure, raw_seat = _canonical_appointment_fields(
            src, **canonical_kwargs,
        )
        if not office:
            return office, office_type, tenure, raw_seat
        try:
            seat = _resolve_appointment_seat(
                db,
                name=person,
                office=office,
                office_type=office_type,
                region_id=raw_seat,
            )
        except OfficeAppointmentRejection:
            # Typed seat reject only: missing/unknown region keeps raw for identity compare.
            seat = raw_seat
        return office, office_type, tenure, seat

    payload_fields = _fields(payload)
    return bool(payload_fields[0]) and payload_fields == _fields(item)

