def require_explicit_xiexang_fields(
    *,
    amount: object = 0,
    account: str = "",
    purpose: str = "",
    target_kind: str = "",
    target_id: str = "",
    cadence: str = "",
) -> Dict[str, Any]:
    """#1503 单一权威接缝：严格验形并归一 typed 字段。"""
    from ming_sim.strict_types import strict_int

    facts: list = []

    def _note(field: str, *, current: object, expected: object) -> None:
        facts.append({"field": field, "current": current, "expected": expected})

    try:
        n = strict_int(amount, accept_numeric_strings=False)
    except ValueError:
        n = 0
    if n <= 0:
        _note("amount", current=amount, expected={"type": "positive_int"})
    # #1620：太仓→国库唯一权威 resolve_grant_account；此处不再平行 if。
    canonical_account = resolve_grant_account(grant_action="协饷", account=account)
    if canonical_account not in {"国库", "内库"}:
        _note("account", current=account, expected=["国库", "内库"])
    purpose_cur = str(purpose or "").strip()
    if purpose_cur != "补饷":
        _note("purpose", current=purpose_cur or purpose, expected="补饷")
    canonical_target_kind = str(target_kind or "").strip()
    if canonical_target_kind not in XIEXIANG_TARGET_KINDS:
        _note(
            "target_kind",
            current=canonical_target_kind or target_kind,
            expected=sorted(XIEXIANG_TARGET_KINDS),
        )
    target_id_cur = str(target_id or "").strip()
    if not target_id_cur:
        _note("target_id", current=target_id, expected={"nonempty_str": True})
    cadence_value = str(cadence or "").strip()
    if cadence_value and cadence_value not in {"一次性", "每月"}:
        _note(
            "cadence",
            current=cadence_value,
            expected=["一次性", "每月", ""],
        )
    if facts:
        raise IncompleteXiexangPayloadError(field_failures=facts)
    return {
        "amount": n,
        "account": canonical_account,
        "purpose": "补饷",
        "target_kind": canonical_target_kind,
        "target_id": target_id_cur,
    }

def office_leverage_multiplier(office: object, already_normalized: bool = False) -> float:
    """Map an office title to the faction-leverage rank multiplier via offices.json.

    Comma-separated concurrent titles take the highest recognized multiplier. Titles with
    no leverage-bearing stem keep the historical conservative default 1.0.
    """
    del already_normalized  # retained for the historical caller contract
    parts = concurrent_office_titles(office)
    if not parts:
        return DEFAULT_LEVERAGE_MULTIPLIER

    table = _table()
    office_weights: list[float] = []
    for part in parts:
        matches: list[tuple[int, float]] = []
        modifiers: list[float] = []
        for rule in _iter_rank_rules(table):
            if "leverage_multiplier" not in rule:
                continue
            for stem in rule.get("stems") or []:
                token = str(stem or "").strip()
                if not token or token not in part:
                    continue
                weight = float(rule["leverage_multiplier"])
                if token in {"候补", "候用"}:
                    modifiers.append(weight)
                else:
                    matches.append((len(token), weight))
        if matches or modifiers:
            longest = max((length for length, _weight in matches), default=-1)
            base_weights = [weight for length, weight in matches if length == longest]
            # Longest title stem identifies the office; explicit status modifiers then
            # constrain it. This preserves old min-within-title semantics without letting
            # generic substrings (御史 inside 佥都御史) demote the base title.
            office_weights.append(min([*base_weights, *modifiers]))
    # Concurrent offices contribute at the strongest real office, as before.
    return max(office_weights, default=DEFAULT_LEVERAGE_MULTIPLIER)

def gate_key_form_error(key: str) -> str:
    """trigger_gate key 形态校验（#12 Q3 fail-loud，ADR 0012 残留 4b①）。合法→""；非法→错误说明。
    bare key（无 "."）须是已知 metric；点分 key 首段须是合法表名、结构完整（去末段聚合后 ≥3 段）。
    字段名(列)是否存在由 _eval_gate_key 运行期对 DB schema 兜底（content load 无 DB 不校验列）。"""
    if "." not in key:
        if key not in GATE_METRIC_KEYS:
            return f"未知 metric「{key}」（须 {'/'.join(GATE_METRIC_KEYS)} 之一，或用 表.id.字段 形式）"
        return ""
    parts = key.split(".")
    if parts[0] not in GATE_TABLES:
        return f"未知表「{parts[0]}」（须 {'/'.join(GATE_TABLES)} 之一）"
    if parts[-1] in GATE_AGG_FUNCS:
        parts = parts[:-1]
    if len(parts) < 3:
        return "结构不完整（应形如 表.id.字段[.聚合]）"
    # 拒空段（cmr r1 codex）：空 id / 空字段 / | 列表含空成员 → 静默不达标或 SQL 崩，须 fail-loud
    field = parts[-1]
    id_segment = ".".join(parts[1:-1])
    if not field.strip() or not id_segment.strip():
        return "id 或 字段 为空"
    if any(not m.strip() for m in id_segment.split("|")):
        return "id 列表含空成员（| 分隔）"
    # class.<名>[@<region>] 成员校验（cmr r2/online concur）：类名（@ 前）非空；带 @ 者 region
    # （@ 后）也须非空——空 region 的 @ 是「想写 regional 却漏 region」的 malformed regional gate，
    # runtime 会静默回退 national class 行（应 fail-loud；online codex P2）。national 用无 @ 形式。
    if parts[0] == "class":
        for member in id_segment.split("|"):
            if not member.split("@", 1)[0].strip():
                return "class 名为空（@ 前）"
            if "@" in member and not member.split("@", 1)[1].strip():
                return "class @ 后 region 为空（regional gate 须指定 region；national 用无 @ 形式）"
    if parts[0] == "event" and field != "triggered":
        return "event 数值 gate 仅支持 triggered 字段（形如 event.<event_id>.triggered）；文本 gate 用 terminal_state/terminal_reason"
    return ""

def _consume_rescript_answers(
    session: Any, chain: Dict[str, Any], *, source: Provenance,
) -> None:
    """把已裁批红接回案卷 / 请旨续推；幂等，已落不动。

    同一旨 / 同一世界段多问须全部答完才续推一次（ADR 0157 步骤 4）。
    """
    db, state = session.db, session.state
    turn = int(state.turn)
    from ming_sim.rescript_draft import consume_memorial_answers
    consume_memorial_answers(session, chain, source=source)
    rows = db.list_pending_decisions(turn)
    decided = [r for r in rows if str(r.get("status") or "") == "decided"]
    if not decided:
        return

    def _answer_from_row(row: Dict[str, object]) -> Dict[str, object]:
        choice = row.get("choice") if isinstance(row.get("choice"), dict) else {}
        return {
            **row, "choice": dict(choice),
            "label": str(choice.get("label") or ""),
            "hint": str(choice.get("hint") or ""),
            "note": str(choice.get("note") or ""),
            "context": str(row.get("context") or ""),
            "event_id": str(row.get("event_id") or ""),
            "title": str(row.get("title") or ""),
        }

    for row in decided:
        event_id = str(row.get("event_id") or "")
        if event_id.startswith("deliberation:"):
            from ming_sim.rescript_actions import apply_imperial_deliberation_push
            original = db.get_decree_dossier(int(event_id.partition(":")[2]))
            if (row["choice"] or {}).get("action") == "imperial_push" and (original["payload"] or {}).get("deliberation_state") == "stalled":
                with atomic(db):
                    apply_imperial_deliberation_push(
                        db, state, target_dossier_id=int(original["id"]),
                        decision_key=row["decision_key"],
                        decree_text=(row.get("choice") or {}).get("note", ""),
                    )
            continue
        if not event_id.startswith("dossier:"):
            continue
        choice = row.get("choice") if isinstance(row.get("choice"), dict) else {}
        _apply_decided_triad(db, state, row, choice, content=session.content)

    world_rows = [
        r for r in rows
        if str(r.get("event_id") or "").startswith(_WORLD_QUESTION_PREFIX)
        and int(str(r["event_id"]).rsplit(":", 1)[1]) >= int(chain.get("world_question_offset", 0))
    ]
    if (
        world_rows
        and all(str(r.get("status") or "") == "decided" for r in world_rows)
        and chain.get("world_questions")
    ):
        _record_world_question_event_choices(db, state, chain, world_rows, turn=turn)
        continue_world_after_answers(
            session, chain,
            answers=[_answer_from_row(r) for r in sorted(world_rows, key=lambda r: r["answer_order"])],
            source=source,
        )

    decree_rows_by_ref: Dict[str, List[Dict[str, object]]] = {}
    for row in rows:
        event_id = str(row.get("event_id") or "")
        if not event_id.startswith(_DECREE_QUESTION_PREFIX):
            continue
        body = event_id[len(_DECREE_QUESTION_PREFIX):]
        ref, _, idx = body.rpartition(":")
        if int(idx) < int((chain.get("decree_question_offsets") or {}).get(ref, 0)):
            continue
        decree_rows_by_ref.setdefault(ref, []).append(row)
    for ref, ref_rows in decree_rows_by_ref.items():
        if not all(str(r.get("status") or "") == "decided" for r in ref_rows):
            continue
        continue_decree_after_answers(
            session, decree_ref=ref, chain=chain,
            answers=[_answer_from_row(r) for r in sorted(ref_rows, key=lambda r: r["answer_order"])],
            source=source,
        )

def coerce_beyond_intent_flag(value: object) -> int:
    """闭世界肯定识别器：仅契约内肯定表示 →1；缺席/否定/空/畸形一律 →0。

    肯定：True / 非零 int·float / 肯定串集 {"1","true","yes","on","是","有","真"}。
    开放兜底永不得回归——畸形输入不得捏造肯定标记（0072/0118 真相层）。
    """
    if value is None:
        return 0
    if isinstance(value, bool):
        return 1 if value else 0
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return 1 if int(value) != 0 else 0
    text = str(value).strip().lower()
    return 1 if text in {"1", "true", "yes", "on", "是", "有", "真"} else 0

def project_court_roster_rows(
    rows: list[Any], knowledge: Dict[str, object], office_type: str,
) -> list[Any]:
    """Project complete structured roster rows through one character's view.

    The complete roster remains an internal query result.  A personnel-domain
    capability may expose it; otherwise only the reader's current role roster
    and people named in already-authorized events cross the output boundary.
    """
    world = knowledge.get("world") or {}
    if "personnel" in world:
        return list(rows)
    current_office_type = str(knowledge.get("office_type") or office_type or "")
    visible_event_text = "\n".join(
        "：".join(str(value) for value in (item.get("title"), item.get("body")) if value)
        for item in [*(knowledge.get("public_events") or []), *(knowledge.get("events") or [])]
    )
    return [
        row for row in rows
        if str(row["office_type"] or "") == current_office_type
        or str(row["name"] or "") in visible_event_text
    ]

