def _select_second_verdict(
    awaiting: bool, hostile: int, pending: list[dict], history: list[dict],
) -> dict:
    """Read the second judgment from the production owner for its current phase."""
    source = pending if awaiting else history
    matches = [row for row in source if int(row.get("dossier_id", -1)) == hostile]
    if len(matches) != 1:
        raise RuntimeError(
            f"second judgment must contain hostile dossier exactly once; got {len(matches)}"
        )
    verdict = matches[0]
    if verdict.get("decision") not in {"promulgated", "rejected"}:
        raise RuntimeError("second judgment has an empty or illegal decision")
    return verdict

def _render_field_specs(
    specs: Sequence[Tuple[str, FieldSpec]],
) -> Tuple[List[str], List[str]]:
    """Render transport examples and action-scoped constraints from catalog rows."""
    lines: List[str] = []
    notes: List[str] = []
    seen_zh: set = set()
    for action, spec in specs:
        prefix = f"{action}·" if action else ""
        if spec.allowed is not None:
            values = sorted(spec.allowed, key=lambda value: (value != "无", value))
            example = f'"{"|".join(values)}"'
        elif spec.as_int:
            example = "null" if spec.default is None else "0"
            if spec.int_lo > 0 or spec.quantity_unit:
                constraint = (
                    f"可null；命中 JSON integer>={spec.int_lo}；禁数字字符串"
                    if spec.default is None
                    else f"JSON integer>={spec.int_lo}"
                )
                if spec.quantity_unit:
                    constraint += f"；单位={spec.quantity_unit}"
                notes.append(f"{prefix}{spec.zh}：{constraint}")
        else:
            example = '""'
        if spec.zh not in seen_zh:
            seen_zh.add(spec.zh)
            lines.append(f'  "{spec.zh}": {example},')
        if spec.populated_when is not None:
            controller_name, controller_values = spec.populated_when
            controller = _field_specs()[controller_name]
            values = "|".join(sorted(controller_values))
            notes.append(
                f"{prefix}{spec.zh}：仅{controller.zh}={values}时填写；其它留空"
            )
    return lines, notes

def attach_pending_action_endorsement(
    self, action_id: int, entry: Mapping[str, object], *, commit: bool = True,
) -> None:
    """#1842：把本轮背书挂进暂存载荷 endorsements 列表（不造待背书表）。"""
    aid = int(action_id)
    row = self.conn.execute(
        "SELECT payload_json, status FROM pending_actions WHERE id=?",
        (aid,),
    ).fetchone()
    if row is None:
        raise KeyError(f"暂存动作不存在：{aid}")
    if str(row["status"] or "") != "pending":
        raise ValueError(f"暂存动作状态不可挂背书：{row['status']}")
    try:
        payload = json.loads(str(row["payload_json"] or "{}"))
    except (TypeError, ValueError):
        payload = {}
    if not isinstance(payload, dict):
        payload = {}
    form = str(entry.get("form") or "").strip()
    endorser_id = str(entry.get("endorser_id") or "").strip()
    imperial = bool(entry.get("imperial", False))
    source_cid = int(entry.get("source_chat_turn_id") or 0)
    # 暂存阶段尚无 dossier：只验形式/人物/来源轮（与 _validate 同口径）。
    if form == "御笔手敕":
        imperial, endorser_id = True, ""
    if form not in {"会签", "当面站台", "御笔手敕"}:
        raise ValueError("背书形式非法")
    if form == "御笔手敕":
        if not imperial or endorser_id:
            raise ValueError("御笔手敕必须使用御笔标记且不得具名大臣")
    else:
        if imperial or not endorser_id:
            raise ValueError("会签/当面站台必须具名背书人")
        if self.conn.execute(
            "SELECT 1 FROM characters WHERE name=?", (endorser_id,),
        ).fetchone() is None:
            raise ValueError("背书人物不存在")
    if source_cid <= 0:
        raise ValueError("背书来源对话轮 id 须为正整数")
    if self.conn.execute(
        "SELECT 1 FROM chat_turns WHERE id=?", (source_cid,),
    ).fetchone() is None:
        raise ValueError("背书来源对话轮不存在")
    items = list(payload.get("endorsements") or [])
    if not isinstance(items, list):
        items = []
    # 同轮同形同人去重（INSERT OR IGNORE 同语义）。
    key = (form, endorser_id, imperial, source_cid)
    kept = []
    for raw in items:
        if not isinstance(raw, Mapping):
            continue
        k = (
            str(raw.get("form") or "").strip(),
            str(raw.get("endorser_id") or "").strip(),
            bool(raw.get("imperial", False)),
            int(raw.get("source_chat_turn_id") or 0),
        )
        if k == key:
            continue
        kept.append(dict(raw))
    kept.append({
        "form": form, "endorser_id": endorser_id,
        "imperial": imperial, "source_chat_turn_id": source_cid,
    })
    payload["endorsements"] = kept
    self.conn.execute(
        "UPDATE pending_actions SET payload_json=? WHERE id=?",
        (json.dumps(payload, ensure_ascii=False), aid),
    )
    if commit and (
        not bool(getattr(self.conn, "_commit_suspended", False))
        and int(getattr(self.conn, "_atomic_depth", 0) or 0) == 0
    ):
        self.conn.commit()

