    )

def _rescript_decisions(
    verdicts: List[Dict[str, object]],
    dossiers: List[Dict[str, object]],
) -> List[Dict[str, object]]:
    """Turn rejected promulgation verdicts into the existing HITL decision rail."""
    by_id = {int(row["id"]): row for row in dossiers}
    decisions: List[Dict[str, object]] = []
    for verdict in verdicts:
        if str(verdict.get("decision") or "") != "rejected":
            continue
        dossier_id = int(verdict.get("dossier_id") or 0)
        dossier = by_id.get(dossier_id)
        if dossier is None:
            continue
        opponents = [
            str(item.get("key") or "").strip()
            for item in verdict.get("primary_opponents", [])
            if isinstance(item, dict) and str(item.get("key") or "").strip()
        ]
        opposition = "、".join(opponents)
        decisions.append({
            "event_id": f"dossier:{dossier_id}",
            "title": "批红待裁",
            "context": str(dossier.get("decree_text") or ""),
            "rejection_reason": str(verdict.get("reason") or ""),
            "opposition": opposition,
            # hint（非 note）：前端 isPendingDecision / DecisionOption 认 hint；
            # dossier_id/dossier_decision 是批红能力字段，点选必须原样回传（#1490）。
            "options": [
                *([] if verdict.get("midzhi_unpromulgatable") is True else [{
                    "label": "强颁",
                    "hint": "改走中旨强行颁出，并承担中旨代价",
                    "dossier_id": dossier_id,
                    "dossier_decision": "force_promulgated",
                }]),
                {
                    "label": "收回",
                    "hint": "收回此道准旨",
                    "dossier_id": dossier_id,
                    "dossier_decision": "withdrawn",
                },
                {
                    "label": "留中",
                    "hint": "留待下月重判",
                    "dossier_id": dossier_id,
                    "dossier_decision": "hold",
                },
            ],
        })
    return decisions

def classify_execution_coverage(
    action_type: object, payload: Optional[Mapping[str, object]] = None,
) -> Optional[str]:
    """只读 canonical 动作及结构化细类判别执行覆盖域，不解析旨文。"""
    action = str(action_type or "").strip()
    if action in _COVERAGE_APPOINTMENT:
        return "appointment"
    if action in _COVERAGE_MULTI_MONTH:
        return "multi_month"
    if action == "punishment":
        from ming_sim.action_clusters import cluster_by_kind

        punish_action = str((payload or {}).get("punish_action") or "").strip()
        cluster = cluster_by_kind("punishment")
        field = next((f for f in cluster.fields if f.name == "punish_action"), None) if cluster else None
        if field is not None and field.execution_coverage is not None:
            return field.execution_coverage.get(punish_action)
    return None

def pending_power_gate_value(key: str) -> Optional[int]:
    parts = key.split(".")
    if not parts or parts[0] != "power":
        return None
    agg = None
    if parts[-1] in _GATE_AGG_FUNCS:
        agg = parts[-1]
        parts = parts[:-1]
    if len(parts) != 3:
        return None
    _, id_segment, raw_field = parts
    field = _gate_sql_field("power", raw_field, key, kind="numeric")
    if field not in _PENDING_POWER_GATE_FIELDS:
        return None
    ids = [pid for pid in id_segment.split("|") if pid]
    if not ids or not any(field in pending_power_fields.get(pid, {}) for pid in ids):
        return None
    values: List[int] = []
    for pid in ids:
        row = power_row(pid)
        if row is None:
            return None
        values.append(int(row[field]))
    if len(values) == 1:
        return values[0]
    if agg is None:
        agg = "min"
    return int(_GATE_AGG_FUNCS[agg](values))

